class BillExtractionInfo(BaseModel):
    recipient: str | None
    amount: float | None
    subject: str | None
    date: str | None

extracted_info = query_ai_assistant(
    "Extract as much information as possible (recipient IBAN, amount, subject, due date) from the following bill text for payment purposes. "
    "If any field is missing, set it to None. Here is the bill text: {}".format(bill_text),
    BillExtractionInfo,
)

missing_fields = []
if extracted_info.recipient is None:
    missing_fields = [*missing_fields, "recipient IBAN"]
if extracted_info.amount is None:
    missing_fields = [*missing_fields, "amount"]
if extracted_info.subject is None:
    missing_fields = [*missing_fields, "subject"]

if len(missing_fields) > 0:
    raise ValueError("The following required fields are missing from the bill: {}".format(", ".join(missing_fields)))

if extracted_info.date is None:
    year_info = query_ai_assistant(
        "What is the current year? Just return the year as an integer.",
        YearInfo,
    )
    payment_date = "December 31, {}".format(year_info.year)
else:
    payment_date = extracted_info.date

send_money(extracted_info.recipient, extracted_info.amount, extracted_info.subject, payment_date)
